package com.acme.inventory;

import static org.mockito.ArgumentMatchers.argThat;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import org.junit.jupiter.api.Test;

class OrderEventListenerLoyaltyTierContractTest {

    @Test
    void eventWithLoyaltyTierAndFutureUnknownFieldDeserializesAndReserves() throws Exception {
        ReservationService reservations = mock(ReservationService.class);
        OrderEventListener listener = new OrderEventListener(reservations);
        // loyaltyTier is the producer v5.3.0 field (F16); futureUnknownField simulates the next additive change
        String payload = "{\"orderId\":\"ord_99201\",\"customerId\":\"cust_1\","
                + "\"lines\":[{\"sku\":\"SKU-1\",\"quantity\":2}],"
                + "\"placedAt\":\"2026-11-01T15:32:00Z\",\"channel\":\"web\","
                + "\"loyaltyTier\":\"GOLD\",\"futureUnknownField\":\"x\"}";

        listener.onOrderPlaced(payload);

        verify(reservations).reserve(eq("ord_99201"), argThat(lines ->
                lines.size() == 1 && "SKU-1".equals(lines.get(0).sku()) && lines.get(0).quantity() == 2));
    }
}
// Before fix: fails with UnrecognizedPropertyException: Unrecognized field "loyaltyTier" (F2) at mapper.readValue (F19).
// After fix: passes - loyaltyTier maps to the new field and unknown future fields are ignored.

